-- As-of features: future events can affect LABEL only, never model inputs.
CREATE OR REPLACE VIEW EDITION_FEATURES AS
SELECT s.DATASET_ID, s.READER_ID, s.BRAND, s.SUBSCRIBED, s.SNAPSHOT_DATE,
       s.STARTED_DATE, s.OBSERVED_UNTIL, s.SPLIT_NAME,
       IFF(s.SUBSCRIBED, 'churn', 'sales') AS KIND,
       COALESCE(COUNT_IF(e.EVENT_TYPE = 'visit' AND e.EVENT_DATE >= DATEADD(day,-30,s.SNAPSHOT_DATE) AND e.EVENT_DATE < s.SNAPSHOT_DATE),0) AS VISITS_30D,
       COUNT(DISTINCT IFF(e.EVENT_TYPE = 'visit' AND e.EVENT_DATE >= DATEADD(day,-30,s.SNAPSHOT_DATE) AND e.EVENT_DATE < s.SNAPSHOT_DATE,e.EVENT_DATE,NULL)) AS ACTIVE_DAYS_30D,
       COALESCE(COUNT_IF(e.EVENT_TYPE = 'premium_read' AND e.EVENT_DATE >= DATEADD(day,-30,s.SNAPSHOT_DATE) AND e.EVENT_DATE < s.SNAPSHOT_DATE),0) AS PREMIUM_READS_30D,
       FLOOR(DATEDIFF(day,s.STARTED_DATE,s.SNAPSHOT_DATE)/30) AS TENURE_MONTHS,
       LEAST(90,COALESCE(DATEDIFF(day,MAX(IFF(e.EVENT_TYPE = 'visit' AND e.EVENT_DATE < s.SNAPSHOT_DATE,e.EVENT_DATE,NULL)),s.SNAPSHOT_DATE),90)) AS DAYS_SINCE_VISIT,
       COALESCE(COUNT_IF(e.EVENT_TYPE = 'payment_failure' AND e.EVENT_DATE >= DATEADD(day,-90,s.SNAPSHOT_DATE) AND e.EVENT_DATE < s.SNAPSHOT_DATE),0) AS PAYMENT_FAILURES_90D,
       IFF(COUNT_IF(e.EVENT_TYPE = IFF(s.SUBSCRIBED,'cancel','subscribe') AND e.EVENT_DATE >= s.SNAPSHOT_DATE AND e.EVENT_DATE < DATEADD(day,30,s.SNAPSHOT_DATE)) > 0,1,0) AS LABEL
FROM EDITION_SNAPSHOTS s LEFT JOIN EDITION_EVENTS e
  ON s.DATASET_ID=e.DATASET_ID AND s.READER_ID=e.READER_ID
WHERE s.OBSERVED_UNTIL >= DATEADD(day,30,s.SNAPSHOT_DATE) AND s.STARTED_DATE <= s.SNAPSHOT_DATE
GROUP BY s.DATASET_ID,s.READER_ID,s.BRAND,s.SUBSCRIBED,s.SNAPSHOT_DATE,s.STARTED_DATE,s.OBSERVED_UNTIL,s.SPLIT_NAME;
